import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [2, 3, 4]
DELAY_SECONDS = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    outputs = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                outputs.append(dev)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                _cleanup(outputs)
                sys.exit(1)

        while _running:
            for dev in outputs:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} set to HIGH")
                except DeviceClosed:
                    print(f"Error: GPIO {dev.pin.number} is closed", file=sys.stderr)
                    _cleanup(outputs)
                    sys.exit(1)
                except GPIOZeroError as exc:
                    print(f"Error: failed to set GPIO {dev.pin.number} HIGH: {exc}", file=sys.stderr)
                    _cleanup(outputs)
                    sys.exit(1)

            time.sleep(DELAY_SECONDS)

            for dev in outputs:
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} set to LOW")
                except DeviceClosed:
                    print(f"Error: GPIO {dev.pin.number} is closed", file=sys.stderr)
                    _cleanup(outputs)
                    sys.exit(1)
                except GPIOZeroError as exc:
                    print(f"Error: failed to set GPIO {dev.pin.number} LOW: {exc}", file=sys.stderr)
                    _cleanup(outputs)
                    sys.exit(1)

            time.sleep(DELAY_SECONDS)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        _cleanup(outputs)
        sys.exit(1)

    finally:
        _cleanup(outputs)

def _cleanup(devices):
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import time
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration
I2C_ADDRESS = 0x48
SAMPLE_INTERVAL = 0.1  # seconds
ADC_CHANNEL = 0

# Initialize I2C bus using board pins (GPIO2=SDA, GPIO3=SCL)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Error initializing I2C bus: {e}", file=sys.stderr)
    sys.exit(1)

# Initialize ADS1115 ADC
try:
    adc = ADS.ADS1115(i2c_bus, address=I2C_ADDRESS)
    # Explicit gain setting to avoid bus errors on some backends
    adc.gain = 1
except ValueError as e:
    print(f"Error: ADS1115 not found at address 0x{I2C_ADDRESS:02X}. "
          f"Check wiring and I2C address. Details: {e}", file=sys.stderr)
    sys.exit(1)
except Exception as e:
    print(f"Error initializing ADS1115: {e}", file=sys.stderr)
    sys.exit(1)

# Initialize analog input channel
try:
    analog_channel = AnalogIn(adc, ADC_CHANNEL)
except Exception as e:
    print(f"Error initializing analog channel {ADC_CHANNEL}: {e}", file=sys.stderr)
    sys.exit(1)

def read_adc_value():
    """Reads the ADC value and checks for errors."""
    try:
        # .value returns the raw ADC reading; .is_valid checks for conversion errors
        if not analog_channel.is_valid:
            print("Warning: ADC reading is invalid (conversion error).", file=sys.stderr)
            return None
        return analog_channel.value
    except OSError as e:
        print(f"Error: I2C bus error while reading ADC: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error reading ADC value: {e}", file=sys.stderr)
        return None

def main_loop():
    """Main loop to continuously read and print ADC values."""
    while True:
        adc_value = read_adc_value()
        if adc_value is not None:
            print(f"ADC Channel {ADC_CHANNEL}: {adc_value}")
        time.sleep(SAMPLE_INTERVAL)

if __name__ == "__main__":
    try:
        main_loop()
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        # Clean up I2C bus resources
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Resources released. Exiting.")

