import time
import signal
import sys
from gpiozero import PWMOutputDevice

# BCM pin numbers whose PWM state we will read and report.
PWM_PINS = [1, 2, 3, 4]

# Global list so the signal handler can release resources.
_devices = []

def cleanup():
    """Turn off and close every PWM device, then exit."""
    for dev in _devices:
        try:
            dev.value = 0
            dev.close()
        except Exception:
            pass
    _devices.clear()

def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    cleanup()
    sys.exit(0)

def read_pwm_state(device):
    """Return the current duty cycle of a PWM device, or None on failure."""
    try:
        return device.value
    except Exception as exc:
        print(f"Error reading PWM state: {exc}", file=sys.stderr)
        return None

def main():
    # Register signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialize PWM devices (active_high=True, frequency 100 Hz).
    for pin in PWM_PINS:
        try:
            dev = PWMOutputDevice(pin, active_high=True, initial_value=0, frequency=100)
            _devices.append(dev)
        except Exception as exc:
            print(f"Failed to initialize PWM on GPIO{pin}: {exc}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    print("PWM state reporting started. Press Ctrl+C to stop.")

    try:
        while True:
            for dev in _devices:
                state = read_pwm_state(dev)
                if state is not None:
                    print(f"GPIO{dev.pin.number} PWM duty cycle: {state:.3f}")
                else:
                    print(f"GPIO{dev.pin.number} PWM state: invalid", file=sys.stderr)
            time.sleep(0.1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

