import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
POLL_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_serial_data(ser):
    try:
        data = ser.readline()
        if data:
            print(data.decode('ascii', errors='replace').strip())
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
    except UnicodeDecodeError as e:
        print(f"Decoding error: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            read_serial_data(ser)
            time.sleep(POLL_INTERVAL)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

OUTPUT_PIN = 17

def main() -> int:
    try:
        output = DigitalOutputDevice(OUTPUT_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        return 1

    def cleanup(signum=None, frame=None):
        try:
            output.close()
        except Exception:
            pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        output.on()
        print(f"GPIO {OUTPUT_PIN} set to HIGH")
    except GPIOZeroError as exc:
        print(f"Failed to set GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        cleanup()
        return 1
    finally:
        cleanup()

    return 0

if __name__ == "__main__":
    sys.exit(main())

