import time
import signal
import sys
import board
import busio
from adafruit_mcp3xxx import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_adc(channel: int, adc: MCP3008) -> int | None:
    """Read a single channel from the MCP3008 and validate the result."""
    try:
        pin = AnalogIn(adc, channel)
        value = pin.value
        if not (0 <= value <= 1023):
            print(f"Warning: invalid ADC reading {value} on channel {channel}", file=sys.stderr)
            return None
        return value
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return None

def main() -> None:
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        mcp = MCP3008(i2c, address=0x68)
    except Exception as exc:
        print(f"Failed to initialize MCP3008: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(5):
            if not _running:
                break
            value = read_adc(0, mcp)
            if value is not None:
                print(f"Reading {i + 1}/5: {value}")
            else:
                print(f"Reading {i + 1}/5: skipped due to error", file=sys.stderr)
            if i < 4 and _running:
                time.sleep(60)
    finally:
        try:
            mcp.close()
        except Exception:
            pass
        print("ADC monitoring stopped.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

OUTPUT_PIN = 17
CYCLES = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        output = DigitalOutputDevice(OUTPUT_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(CYCLES):
            if not _running:
                break

            output.on()
            print(f"Cycle {i + 1}/{CYCLES}: GPIO {OUTPUT_PIN} -> HIGH")

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY_SECONDS)

            output.off()
            print(f"Cycle {i + 1}/{CYCLES}: GPIO {OUTPUT_PIN} -> LOW")

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY_SECONDS)

        if _running:
            print("GPIO 17 control sequence completed successfully.")
        else:
            print("Interrupted before completion.", file=sys.stderr)
            sys.exit(130)

    except GPIOZeroError as exc:
        print(f"GPIO error during operation: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        try:
            output.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [9, 10, 11, 12, 13]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_pwm_value():
    try:
        value = float(input("Enter PWM value (0.0-1.0): "))
    except (ValueError, EOFError):
        print("Invalid input. Please enter a numeric value between 0.0 and 1.0.")
        return None
    if not 0.0 <= value <= 1.0:
        print("Invalid input. Please enter a value between 0.0 and 1.0.")
        return None
    return value

def apply_pwm(pin, value):
    try:
        pwm = PWMOutputDevice(pin)
    except GPIOZeroError as e:
        print(f"Failed to initialize PWM on GPIO {pin}: {e}")
        return False
    try:
        pwm.value = value
        print(f"Applied PWM value {value} to GPIO {pin}")
        return True
    finally:
        pwm.close()

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        while _running:
            pwm_value = read_pwm_value()
            if pwm_value is None:
                continue
            for pin in PINS:
                if not _running:
                    break
                apply_pwm(pin, pwm_value)
            break
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

