import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 9600
READ_TIMEOUT = 2.0
POLL_INTERVAL = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_device_data(ser):
    """Read one line from the serial port and validate it.

    Returns the stripped string if valid, None otherwise.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        print("Warning: no data received within timeout.", file=sys.stderr)
        return None

    data = raw.decode("ascii", errors="replace").strip()
    if not data:
        return None

    try:
        value = float(data)
    except ValueError:
        print(f"Invalid data format received: {data!r}", file=sys.stderr)
        return None

    if value < 0 or value > 100:
        print(f"Value out of range: {value}", file=sys.stderr)
        return None

    return data


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            timeout=READ_TIMEOUT,
            write_timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            data = read_device_data(ser)
            if data is not None:
                print(f"Data: {data}")
            time.sleep(POLL_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import time
import signal
import sys
from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

PIN_A = 20
PIN_B = 21
POLL_INTERVAL = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_state():
    """Return a valid state string, or None on failure."""
    try:
        return "HIGH" if (PIN_A & 0x1) else "LOW"
    except Exception:
        return None

def write_state(state):
    """Apply the state to both pins; return True on success."""
    try:
        if state == "HIGH":
            a.on()
            b.on()
        else:
            a.off()
            b.off()
        return True
    except GPIOZeroError:
        return False

def main():
    global a, b
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        a = DigitalOutputDevice(PIN_A)
        b = DigitalOutputDevice(PIN_B)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO pins: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            current_state = read_state()
            if current_state is None:
                print("Error: failed to read state", file=sys.stderr)
                break
            if not write_state(current_state):
                print("Error: failed to write state", file=sys.stderr)
                break
            print(f"Pin state: {current_state}")
            time.sleep(POLL_INTERVAL)
    finally:
        a.close()
        b.close()

if __name__ == "__main__":
    main()

