import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT_S = 2.0
READ_INTERVAL_S = 0.1
MAX_READ_ATTEMPTS = 20

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_data(ser):
    """Read one line from the serial port and validate it."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    data = raw.decode("ascii", errors="replace").strip()
    if not data:
        return None

    if not data.startswith("DATA:"):
        return None

    try:
        value = float(data[5:])
    except ValueError:
        return None

    return value


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            timeout=TIMEOUT_S,
            write_timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        attempts = 0
        while _running and attempts < MAX_READ_ATTEMPTS:
            attempts += 1
            reading = read_data(ser)
            if reading is not None:
                print(f"Reading: {reading}")
                break
            time.sleep(READ_INTERVAL_S)

        if not _running:
            print("Interrupted by signal.", file=sys.stderr)
            sys.exit(130)

        if attempts >= MAX_READ_ATTEMPTS:
            print("No valid data received from device.", file=sys.stderr)
            sys.exit(1)

    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

