import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_S = 1.0
NUM_READINGS = 3
INTERVAL_S = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_serial_data(ser):
    """Read one line from the serial port and decode it."""
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT_S
        )
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        readings_done = 0
        while _running and readings_done < NUM_READINGS:
            data = read_serial_data(ser)
            if data is not None:
                print(f"Reading {readings_done + 1}/{NUM_READINGS}: {data}")
                readings_done += 1
            else:
                print("No data received (device may be absent or not responding).", file=sys.stderr)
                break
            if _running and readings_done < NUM_READINGS:
                time.sleep(INTERVAL_S)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

