import time
import sys
import board
import busio
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration
I2C_ADDRESS = 0x48
SAMPLE_INTERVAL_SECONDS = 1
ADC_CHANNEL = 0


def initialize_adc():
    """Initialize I2C bus and ADS1015 ADC at the specified address."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        ads = ADS.ADS1015(i2c_bus, address=I2C_ADDRESS)
        return ads
    except ValueError as e:
        print(f"Error: No I2C device found at address 0x{I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error: I2C bus error while initializing ADC: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: Failed to initialize ADC: {e}", file=sys.stderr)
        sys.exit(1)


def read_adc_channel(adc, channel):
    """Read and return the ADC value from the specified channel."""
    try:
        chan = AnalogIn(adc, channel)
        return chan.value
    except ValueError as e:
        print(f"Error: Invalid channel {channel}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"Error: I2C bus error while reading ADC: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error: Unexpected error reading ADC: {e}", file=sys.stderr)
        return None


def main():
    """Main loop: initialize ADC, read channel every second, print value."""
    adc = initialize_adc()
    try:
        while True:
            adc_value = read_adc_channel(adc, ADC_CHANNEL)
            if adc_value is not None:
                print(f"ADC Channel {ADC_CHANNEL}: {adc_value}")
            time.sleep(SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Clean up I2C bus resources
        try:
            if 'i2c_bus' in locals():
                i2c_bus.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
