import time
import board
import adafruit_dht

PINS = [board.D4, board.D5, board.D17, board.D23]
running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_sensor(sensor):
    try:
        t = sensor.temperature
        h = sensor.humidity
        if t is None or h is None:
            return None
        if not (-40 <= t <= 80 and 0 <= h <= 100):
            return None
        return t, h
    except RuntimeError:
        return None
    except Exception:
        return None

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    sensors = []
    for pin in PINS:
        try:
            sensors.append(adafruit_dht.DHT22(pin, use_pulseio=False))
        except Exception as e:
            print(f"Failed to init {pin}: {e}", file=sys.stderr)
            sys.exit(1)

    try:
        while running:
            for i, sensor in enumerate(sensors):
                if not running:
                    break
                result = read_sensor(sensor)
                if result is None:
                    print(f"Pin {PINS[i]}: no valid reading")
                else:
                    t, h = result
                    print(f"Pin {PINS[i]}: T={t:.1f}C  H={h:.1f}%")
            if running:
                time.sleep(60)
    finally:
        for sensor in sensors:
            try:
                sensor.exit()
            except Exception:
                pass

