import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [17, 18, 27]
DELAY_SECONDS = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def set_gpio_output(pin: int, value: int) -> None:
    if not 0 <= value <= 255:
        raise ValueError(f"Value {value} out of range for a byte (0-255).")
    try:
        dev = OutputDevice(pin)
    except GPIOZeroError as e:
        print(f"Error: failed to initialize GPIO {pin}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        dev.value = bool(value)
        print(f"GPIO {pin} set to {value}")
    except DeviceClosed:
        print(f"Error: GPIO {pin} device was closed unexpectedly.", file=sys.stderr)
        sys.exit(1)
    except GPIOZeroError as e:
        print(f"Error: failed to set GPIO {pin}: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        dev.close()

def main() -> None:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        while _running:
            for pin in PINS:
                if not _running:
                    break
                set_gpio_output(pin, 255)
                time.sleep(DELAY_SECONDS)
                if not _running:
                    break
                set_gpio_output(pin, 0)
                time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

