import signal
import sys
import time

import paho.mqtt.client as mqtt

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
MQTT_BROKER = "localhost"
MQTT_PORT = 1883
MQTT_TOPIC = "sensor/data"
PUBLISH_INTERVAL = 0.01

running = True


def signal_handler(signum, frame):
    global running
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
    else:
        print(f"Failed to connect to MQTT broker. Reason code: {reason_code}", file=sys.stderr)


def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker. Reason code: {reason_code}", file=sys.stderr)


def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        client.on_connect = on_connect
        client.on_disconnect = on_disconnect

        try:
            client.connect(MQTT_BROKER, MQTT_PORT, keepalive=60)
        except Exception as e:
            print(f"Error: Could not connect to MQTT broker: {e}", file=sys.stderr)
            sys.exit(1)

        client.loop_start()

        while running:
            try:
                data = ser.readline()
                if data:
                    payload = data.decode("utf-8", errors="replace").strip()
                    if payload:
                        info = client.publish(MQTT_TOPIC, payload, qos=0)
                        info.wait_for_publish(timeout=5)
                        print(f"Published: {payload}")
                time.sleep(PUBLISH_INTERVAL)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                break

    finally:
        try:
            client.loop_stop()
            client.disconnect()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

