            for dev in outputs:
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} set to LOW")
                except DeviceClosed:
                    print(f"Error: GPIO {dev.pin.number} is closed", file=sys.stderr)
                    sys.exit(1)
            time.sleep(PERIOD)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in outputs:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

