import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_ADDRESS = 0x48
SAMPLE_INTERVAL_SECONDS = 1
ADC_MAX_VALUE = 32767  # 16-bit signed positive max

def initialize_adc():
    """Initialize I2C bus and ADS1115 ADC at the specified address."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        adc = ADS.ADS1115(i2c_bus, address=I2C_ADDRESS)
        return adc
    except ValueError as e:
        print(f"Error: ADS1115 not found at address 0x{I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing ADC: {e}", file=sys.stderr)
        sys.exit(1)

def read_adc_channel(adc, channel=0):
    """Read and return the ADC value from the specified channel."""
    try:
        chan = AnalogIn(adc, channel)
        return chan.value
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}", file=sys.stderr)
        return None

def main():
    """Main loop: read ADC channel 0 every second and print the value."""
    adc = initialize_adc()
    try:
        while True:
            adc_value = read_adc_channel(adc, 0)
            if adc_value is not None:
                print(f"ADC Value: {adc_value}")
            time.sleep(SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        # Release I2C bus resources
        try:
            adc.i2c.deinitialize()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

INA219_ADDRESS = 0x17
I2C_BUS = 1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_ina219(bus, address):
    """Read the 32-bit bus voltage/current register from the INA219."""
    try:
        write_msg = i2c_msg.write(address, [0x0000])
        read_msg = i2c_msg.read(address, 4)
        bus.i2c_rdwr(write_msg, read_msg)
        return list(read_msg)
    except OSError as exc:
        raise RuntimeError(f"INA219 read failed at 0x{address:02X}: {exc}") from exc


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            read_ina219(bus, INA219_ADDRESS)
        except RuntimeError as exc:
            print(f"Error: INA219 not detected at 0x{INA219_ADDRESS:02X}: {exc}", file=sys.stderr)
            sys.exit(1)

        while _running:
            try:
                data = read_ina219(bus, INA219_ADDRESS)
                print(f"INA219 data: {data}")
            except RuntimeError as exc:
                print(f"Warning: {exc}", file=sys.stderr)
            time.sleep(2)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

