import signal
import sys
from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_temperature():
    """Read and print a single temperature value from the DS18B20."""
    try:
        sensor = W1ThermSensor()
    except NoSensorFoundError:
        print("Error: No DS18B20 sensor found on the 1-Wire bus.", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: Failed to initialize DS18B20 sensor: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        temperature = sensor.get_temperature()
    except SensorNotReadyError:
        print("Error: DS18B20 sensor is not ready (conversion in progress).", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: Failed to read temperature: {exc}", file=sys.stderr)
        sys.exit(1)

    if temperature is None:
        print("Error: Invalid temperature reading (None).", file=sys.stderr)
        sys.exit(1)

    print(f"Temperature: {temperature:.2f} °C")

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        read_temperature()
    finally:
        # w1thermsensor does not hold persistent hardware resources that need
        # explicit release, but we close the underlying 1-Wire bus handle if
        # the library exposes one.  As of the latest version, the sensor object
        # is a thin wrapper; calling close() is safe and idempotent.
        try:
            sensor = W1ThermSensor()
            sensor.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

