import time
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration
I2C_ADDRESS = 0x48
NUM_READINGS = 128
DELAY_SECONDS = 0.05


def initialize_adc():
    """Initialize I2C bus and ADS1115 ADC at the specified address."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ads = ADS.ADS1115(i2c, address=I2C_ADDRESS)
        ads.gain = 1
    except ValueError as e:
        print(f"Error: No device found at I2C address 0x{I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing ADS1115: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        channel = AnalogIn(ads, 0)
    except Exception as e:
        print(f"Error initializing analog channel: {e}", file=sys.stderr)
        sys.exit(1)

    return i2c, ads, channel


def read_adc(channel):
    """Read and print the ADC value. Returns True on success, False on failure."""
    try:
        value = channel.value
        print(f"ADC Value: {value}")
        return True
    except OSError as e:
        print(f"Error reading ADC (device may be unresponsive): {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Unexpected error reading ADC: {e}", file=sys.stderr)
        return False


def main():
    i2c, ads, channel = initialize_adc()
    try:
        for i in range(NUM_READINGS):
            if not read_adc(channel):
                print("Failed to read ADC. Exiting.", file=sys.stderr)
                sys.exit(1)
            time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nInterrupted by user. Exiting gracefully.")
    finally:
        # Release I2C bus resources
        try:
            i2c.deinit()
        except Exception:
            pass
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

