    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    for pin, board_pin in PINS.items():
        if not running:
            break
        print(f"Applying state to pin: {pin}")
        sensor = None
        try:
            sensor = adafruit_dht.DHT22(board_pin, use_pulseio=False)
            temperature, humidity = read_sensor(sensor)
            if temperature is not None and humidity is not None:
                print(f"Pin: {pin}, Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
            else:
                print(f"Pin: {pin}, Failed to read valid data from sensor", file=sys.stderr)
        except Exception as e:
            print(f"Pin: {pin}, Error initializing or reading sensor: {e}", file=sys.stderr)
        finally:
            if sensor is not None:
                try:
                    sensor.exit()
                except Exception:
                    pass
        if running:
            time.sleep(5)

    print("Exiting program.")
    sys.exit(0)


if __name__ == "__main__":
