import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [4, 5, 6, 13, 17, 22, 27]
DELAY = 0.01

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                _cleanup(devices)
                sys.exit(1)

        while _running:
            for dev in devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} set to HIGH")
                except (DeviceClosed, GPIOZeroError) as exc:
                    print(f"Error setting GPIO {dev.pin.number} HIGH: {exc}", file=sys.stderr)
                    _cleanup(devices)
                    sys.exit(1)

            time.sleep(DELAY)

            for dev in devices:
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} set to LOW")
                except (DeviceClosed, GPIOZeroError) as exc:
                    print(f"Error setting GPIO {dev.pin.number} LOW: {exc}", file=sys.stderr)
                    _cleanup(devices)
                    sys.exit(1)

            time.sleep(DELAY)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup(devices)

def _cleanup(devices):
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import signal
import sys
import time
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [12, 13, 18, 19, 22, 23]
running = True


def handle_signal(signum, frame):
    global running
    running = False


def is_valid_reading(value):
    if value is None:
        return False
    if not isinstance(value, (int, float)):
        return False
    if not 0 <= value <= 100:
        return False
    return True


def apply_pwm_state(pwm_devices, value):
    if not is_valid_reading(value):
        print(f"Invalid reading: {value}", file=sys.stderr)
        return
    duty = float(value) / 100.0
    for dev in pwm_devices:
        try:
            dev.value = duty
        except GPIOZeroError as e:
            print(f"Error setting PWM on pin {dev.pin}: {e}", file=sys.stderr)
            return
    print(f"Applied PWM duty cycle: {value}%")


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    pwm_devices = []
    try:
        for pin in PINS:
            try:
                pwm_devices.append(PWMOutputDevice(pin, initial_value=0, frequency=1000))
            except GPIOZeroError as e:
                print(f"Failed to initialize PWM on pin {pin}: {e}", file=sys.stderr)
                running = False
                break
    except Exception as e:
        print(f"Unexpected error during initialization: {e}", file=sys.stderr)
        running = False

    if not running:
        for dev in pwm_devices:
            dev.close()
        sys.exit(1)

    try:
        while running:
            apply_pwm_state(pwm_devices, 50.0)
            time.sleep(2)
    finally:
        for dev in pwm_devices:
            try:
                dev.value = 0
                dev.close()
            except Exception:
                pass
        print("PWM stopped and GPIO cleaned up.")


if __name__ == "__main__":
    main()

