import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 is not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_SCALE = 16384.0

running = True
bus = None

def signal_handler(signum, frame):
    global running
    running = False

def read_word(bus, addr, reg):
    high = bus.read_byte_data(addr, reg)
    low = bus.read_byte_data(addr, reg + 1)
    val = (high << 8) | low
    if val >= 0x8000:
        val -= 0x10000
    return val

def init_mpu6050(bus, addr):
    try:
        bus.write_byte_data(addr, PWR_MGMT_1, 0x00)
        time.sleep(0.1)
    except OSError as e:
        print(f"Error: MPU6050 not found at 0x{addr:02X} or init failed: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    init_mpu6050(bus, MPU6050_ADDR)

    try:
        while running:
            try:
                ax = read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H)
                print(f"Accel X: {ax / ACCEL_SCALE:.3f} g")
            except OSError as e:
                print(f"Warning: read failed: {e}", file=sys.stderr)
            time.sleep(0.1)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

