import time
import signal
import sys
import board
import adafruit_dht

PINS = [board.D4, board.D17, board.D18, board.D22, board.D23, board.D27]
CYCLES = 3
DELAY = 5

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def main():
    sensors = []
    try:
        for pin in PINS:
            try:
                sensors.append(adafruit_dht.DHT22(pin, use_pulseio=False))
            except Exception as e:
                print(f"Failed to init {pin}: {e}", file=sys.stderr)
