        for cycle in range(CYCLES):
            if not running:
                break
            for idx, sensor in enumerate(sensors):
                try:
                    t = sensor.temperature
                    h = sensor.humidity
                    if t is not None and h is not None:
                        print(f"Cycle {cycle+1}, Pin {PINS[idx]}: T={t:.1f}C  H={h:.1f}%")
