import time
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# --- Configuration -----------------------------------------------------------
ADC_ADDRESS = 0x48
SAMPLE_INTERVAL_S = 0.001
MAX_INIT_RETRIES = 5
INIT_RETRY_DELAY_S = 0.1
MAX_READ_RETRIES = 3
READ_RETRY_DELAY_S = 0.01

# --- Initialization ----------------------------------------------------------
# I2C bus setup with error handling and retry logic
i2c = None
for attempt in range(1, MAX_INIT_RETRIES + 1):
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Lock the bus to verify the ADS1115 is present at the expected address
        while not i2c.try_lock():
            pass
        try:
            if not i2c.probe(ADC_ADDRESS):
                raise RuntimeError(
                    f"No device found at I2C address 0x{ADC_ADDRESS:02X} "
                    f"(attempt {attempt}/{MAX_INIT_RETRIES})"
                )
        finally:
            i2c.unlock()
        break
    except Exception as e:
        print(f"I2C init attempt {attempt}/{MAX_INIT_RETRIES} failed: {e}", file=sys.stderr)
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
            i2c = None
        if attempt < MAX_INIT_RETRIES:
            time.sleep(INIT_RETRY_DELAY_S)

if i2c is None:
    print("Failed to initialize I2C bus or detect ADS1115. Exiting.", file=sys.stderr)
    sys.exit(1)

# ADS1115 setup with error handling
ads = None
try:
    ads = ADS.ADS1115(i2c, address=ADC_ADDRESS)
    # Explicit gain setting to ensure the ADC is configured
    ads.gain = 1
except Exception as e:
    print(f"Failed to initialize ADS1115 at 0x{ADC_ADDRESS:02X}: {e}", file=sys.stderr)
    i2c.deinit()
    sys.exit(1)

# Analog input channel setup
channel = None
try:
    channel = AnalogIn(ads, ADS.P0)
except Exception as e:
    print(f"Failed to configure analog input channel: {e}", file=sys.stderr)
    i2c.deinit()
    sys.exit(1)

# --- Main loop ---------------------------------------------------------------
try:
    while True:
        # Read the ADC value with retry logic
        value = None
        for attempt in range(1, MAX_READ_RETRIES + 1):
            try:
                value = channel.value
                break
            except Exception as e:
                print(f"ADC read attempt {attempt}/{MAX_READ_RETRIES} failed: {e}", file=sys.stderr)
                if attempt < MAX_READ_RETRIES:
                    time.sleep(READ_RETRY_DELAY_S)

        if value is None:
            print("Failed to read ADC value after retries. Exiting.", file=sys.stderr)
            break

        # Print the ADC value to the console
        print(value, flush=True)

        # Wait for the specified interval
        time.sleep(SAMPLE_INTERVAL_S)

except KeyboardInterrupt:
    # Handle Ctrl+C gracefully
    print("\nProgram terminated by user.", file=sys.stderr)

finally:
    # Clean up resources on exit
    try:
        if channel is not None:
            channel.close()
    except Exception:
        pass
    try:
        if ads is not None:
            ads.close()
    except Exception:
        pass
    try:
        if i2c is not None:
            i2c.deinit()
    except Exception:
        pass
    print("Resources released. Exiting.", file=sys.stderr)
    sys.exit(0)

import time
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration
I2C_ADDRESS = 0x48
SAMPLE_INTERVAL_SECONDS = 0.5
ADC_CHANNEL = 0


def initialize_adc():
    """Initialize I2C bus and ADS1115 ADC. Exit on failure."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        adc = ADS.ADS1115(i2c_bus, address=I2C_ADDRESS)
        adc.gain = 1
    except ValueError as e:
        print(f"Error: ADS1115 not found at address 0x{I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing ADS1115: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        channel = AnalogIn(adc, ADC_CHANNEL)
    except Exception as e:
        print(f"Error configuring ADC channel {ADC_CHANNEL}: {e}", file=sys.stderr)
        sys.exit(1)

    return adc, channel


def read_adc(channel):
    """Read and print ADC value. Return True on success, False on failure."""
    try:
        voltage = channel.voltage
        if voltage is None:
            print("Warning: ADC reading returned None (invalid).", file=sys.stderr)
            return False
        print(f"ADC Channel {channel.channel}: {voltage:.4f} V")
        return True
    except OSError as e:
        print(f"Error reading ADC (I/O error): {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Error reading ADC: {e}", file=sys.stderr)
        return False


def main():
    """Main loop: sample ADC every 0.5 seconds until interrupted."""
    adc, channel = initialize_adc()
    try:
        while True:
            read_adc(channel)
            time.sleep(SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Release hardware resources on all exit paths
        try:
            if adc is not None:
                adc.gain = None
        except Exception:
            pass
        try:
            if channel is not None:
                channel.close()
        except Exception:
            pass
        try:
            if adc is not None:
                adc.close()
        except Exception:
            pass
        try:
            if channel is not None:
                channel.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 9600
READ_TIMEOUT = 1.0
POLL_INTERVAL = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor_data(ser):
    """Read one line from the serial port and validate it.

    Returns the stripped string if valid, None otherwise.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    data = raw.decode("ascii", errors="replace").strip()
    if not data:
        return None

    try:
        value = float(data)
    except ValueError:
        return None

    if not (0.0 <= value <= 100.0):
        return None

    return data


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            data = read_sensor_data(ser)
            if data is not None:
                print(f"Sensor reading: {data}")
            time.sleep(POLL_INTERVAL)
    finally:
        ser.close()


if __name__ == "__main__":
    main()

