import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

TRIGGER_PIN = 25
POLL_INTERVAL = 0.5
MAX_RETRIES = 3
RETRY_DELAY = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def set_trigger_state(trigger: OutputDevice, state: bool) -> bool:
    """Apply a boolean state to the trigger pin and report it.

    Returns True on success, False if the underlying hardware call fails.
    """
    try:
        trigger.value = state
        print(f"Trigger pin {trigger.pin.number} set to: {state}")
        return True
    except GPIOZeroError as exc:
        print(f"Error setting trigger pin {trigger.pin.number} to {state}: {exc}", file=sys.stderr)
        return False

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        trigger = OutputDevice(TRIGGER_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize trigger pin {TRIGGER_PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            ok = False
            for attempt in range(1, MAX_RETRIES + 1):
                if set_trigger_state(trigger, True):
                    ok = True
                    break
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)

            if not ok:
                print("Failed to set trigger pin HIGH after retries.", file=sys.stderr)
                return 1

            ok = False
            for attempt in range(1, MAX_RETRIES + 1):
                if set_trigger_state(trigger, False):
                    ok = True
                    break
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)

            if not ok:
                print("Failed to set trigger pin LOW after retries.", file=sys.stderr)
                return 1

            time.sleep(POLL_INTERVAL)
    finally:
        try:
            trigger.close()
        except Exception:
            pass

    return 0

if __name__ == "__main__":
    sys.exit(main())

