import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [18, 23]
CYCLES = 5
DELAY = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    outputs = []
    try:
        for pin in PINS:
            dev = DigitalOutputDevice(pin)
            outputs.append(dev)

        for i in range(CYCLES):
            if not _running:
                break

            state = i % 2
            for dev in outputs:
                dev.value = bool(state)

            print(f"Cycle {i + 1}/{CYCLES}: GPIO 18={state}, GPIO 23={state}")

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY)

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in outputs:
            try:
                dev.close()
            except Exception:
                pass

