import signal
import sys
from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [15, 20, 21]

_outputs = []

def cleanup(signum=None, frame=None):
    for dev in _outputs:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    for pin in PINS:
        try:
            dev = DigitalOutputDevice(pin)
            _outputs.append(dev)
        except GPIOZeroError as e:
            print(f"Failed to initialize GPIO {pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    for pin, dev in zip(PINS, _outputs):
        try:
            dev.on()
            print(f"GPIO {pin} set to HIGH")
        except GPIOZeroError as e:
            print(f"Failed to set GPIO {pin} HIGH: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        signal.pause()
    finally:
        cleanup()

if __name__ == "__main__":
    main()

