import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
POLL_INTERVAL = 0.1

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    data = raw.decode('ascii', errors='replace').strip()
    if not data:
        return None
    try:
        value = float(data)
    except ValueError:
        return None
    if not -273.15 <= value <= 100.0:
        return None
    return value

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            start = time.monotonic()
            reading = read_sensor_data(ser)
            if reading is not None:
                print(f"Sensor reading: {reading:.2f} C")
            elapsed = time.monotonic() - start
            remaining = POLL_INTERVAL - elapsed
            if remaining > 0:
                time.sleep(remaining)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

import time
import sys
import signal
from smbus2 import SMBus, i2c_msg

BMP280_ADDR = 0x76
BMP280_CHIP_ID = 0x58

REG_CHIP_ID = 0xD0
REG_RESET = 0xE0
REG_CTRL_MEAS = 0xF4
REG_PRESS_MSB = 0xF7
REG_TEMP_MSB = 0xFA

CTRL_MEAS_VAL = 0x24  # pressure x1, normal mode

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_reg(bus, addr, reg, length=1):
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, length)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)


def read_bmp280(bus, addr):
    chip_id = read_reg(bus, addr, REG_CHIP_ID)[0]
    if chip_id != BMP280_CHIP_ID:
        raise RuntimeError(f"BMP280 not found (chip_id=0x{chip_id:02X}, expected 0x{BMP280_CHIP_ID:02X})")

    ctrl_meas = read_reg(bus, addr, REG_CTRL_MEAS)[0]
    if (ctrl_meas & 0x18) != CTRL_MEAS_VAL:
        write_reg(bus, addr, REG_CTRL_MEAS, CTRL_MEAS_VAL)

    raw = read_reg(bus, addr, REG_PRESS_MSB, 6)
    if len(raw) < 6:
        raise RuntimeError("Incomplete pressure/temperature data")

    press_raw = (raw[0] << 12) | (raw[1] << 4) | (raw[2] >> 4)
    temp_raw = (raw[3] << 12) | (raw[4] << 4) | (raw[5] >> 4)

    if press_raw == 0 or temp_raw == 0:
        raise RuntimeError("Invalid pressure or temperature reading (all zeros)")

    return press_raw, temp_raw


def write_reg(bus, addr, reg, value):
    write_msg = i2c_msg.write(addr, [reg, value & 0xFF])
    bus.i2c_rdwr(write_msg)


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(1)
    except Exception as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            read_bmp280(bus, BMP280_ADDR)
        except Exception as e:
            print(f"Error: BMP280 not detected at 0x{BMP280_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        for i in range(2):
            if not running:
                break
            try:
                press, temp = read_bmp280(bus, BMP280_ADDR)
                print(f"Reading {i + 1}/2: pressure=0x{press:04X}, temp=0x{temp:04X}")
            except Exception as e:
                print(f"Error: reading failed: {e}", file=sys.stderr)
                sys.exit(1)
            if i < 1:
                time.sleep(1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

