import time
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
ADC_ADDRESS = 0x48
SAMPLE_INTERVAL_SECONDS = 0.5
ADC_MAX_VALUE = 32767  # 16-bit signed positive max

def initialize_adc():
    """Initialize I2C bus and ADS1115 ADC at the specified address."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        ads = ADS.ADS1115(i2c_bus, address=ADC_ADDRESS)
        return ads
    except ValueError as e:
        print(f"Error: ADS1115 not found at address 0x{ADC_ADDRESS:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing ADC: {e}", file=sys.stderr)
        sys.exit(1)

def read_adc_channel(adc, channel):
    """Read and return the ADC value from the specified channel."""
    try:
        chan = AnalogIn(adc, channel)
        return chan.value
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}", file=sys.stderr)
        return None

def main():
    """Main loop: read ADC channel 0 every 0.5 s and print the value."""
    adc = initialize_adc()
    try:
        while True:
            adc_value = read_adc_channel(adc, 0)
            if adc_value is not None:
                print(f"ADC Value: {adc_value}")
            time.sleep(SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Release I2C bus resources
        try:
            if 'i2c_bus' in locals():
                i2c_bus.deinit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

