import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

BME280_I2C_ADDR = 0x76
BME280_CHIP_ID_REG = 0xD0
BME280_CHIP_ID = 0x60
BME280_CTRL_HUM_REG = 0xF2
BME280_CTRL_MEAS_REG = 0xF4
BME280_DATA_REG = 0xF7
BME280_RESET_REG = 0xE0

I2C_BUS = 1
READ_INTERVAL_S = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    msg = i2c_msg.write(BME280_I2C_ADDR, [reg, value])
    bus.i2c_rdwr(msg)


def _read_reg(bus, reg):
    write_msg = i2c_msg.write(BME280_I2C_ADDR, [reg])
    read_msg = i2c_msg.read(BME280_I2C_ADDR, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)[0]


def _read_block(bus, reg, length):
    write_msg = i2c_msg.write(BME280_I2C_ADDR, [reg])
    read_msg = i2c_msg.read(BME280_I2C_ADDR, length)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)


def _validate_chip_id(bus):
    chip_id = _read_reg(bus, BME280_CHIP_ID_REG)
    if chip_id != BME280_CHIP_ID:
        raise RuntimeError(
            f"Invalid chip ID 0x{chip_id:02X} at 0x{BME280_I2C_ADDR:02X}; "
            f"expected 0x{BME280_CHIP_ID:02X} (BME280, not BMP280)."
        )


def _configure_bus(bus):
    _validate_chip_id(bus)
    _write_reg(bus, BME280_CTRL_HUM_REG, 0x01)
    _write_reg(bus, BME280_CTRL_MEAS_REG, 0x24)


def _read_raw(bus):
    data = _read_block(bus, BME280_DATA_REG, 8)
    raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
    raw_hum = (data[6] << 8) | data[7]
    return raw_temp, raw_press, raw_hum


def _sensible_ranges(raw_temp, raw_press, raw_hum):
    if not (0 <= raw_temp <= 0xFFFFF):
        return False
    if not (0 <= raw_press <= 0xFFFFF):
        return False
    if not (0 <= raw_hum <= 0xFFFF):
        return False
    return True


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _configure_bus(bus)
        except OSError as exc:
            print(
                f"Error: BME280 not responding at 0x{BME280_I2C_ADDR:02X}: {exc}",
                file=sys.stderr,
            )
            sys.exit(1)

        while _running:
            try:
                raw_temp, raw_press, raw_hum = _read_raw(bus)
            except OSError as exc:
                print(f"Warning: I2C read failed: {exc}", file=sys.stderr)
                time.sleep(READ_INTERVAL_S)
                continue

            if not _sensible_ranges(raw_temp, raw_press, raw_hum):
                print(
                    f"Warning: out-of-range reading "
                    f"T={raw_temp} P={raw_press} H={raw_hum}",
                    file=sys.stderr,
                )
                time.sleep(READ_INTERVAL_S)
                continue

            print(
                f"T={raw_temp:05d} P={raw_press:05d} H={raw_hum:04d}"
            )

            for _ in range(READ_INTERVAL_S):
                if not _running:
                    break
                time.sleep(1)

    finally:
        bus.close()


if __name__ == "__main__":
    main()

