import sys
from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
VL53L0X_ADDR = 0x29
POLL_INTERVAL = 0.1

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_distance(bus):
    try:
        write_msg = i2c_msg.write(VL53L0X_ADDR, [0x00])
        read_msg = i2c_msg.read(VL53L0X_ADDR, 2)
        bus.i2c_rdwr(write_msg, read_msg)
        data = list(read_msg)
        if len(data) < 2:
            return None
        return (data[0] << 8) | data[1]
    except OSError:
        return None

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        if not bus.read_byte(VL53L0X_ADDR):
            print(f"Error: no device found at 0x{VL53L0X_ADDR:02X} on bus {I2C_BUS}", file=sys.stderr)
            sys.exit(1)

        while running:
            distance = read_distance(bus)
            if distance is None:
                print("Error: failed to read from VL53L0X", file=sys.stderr)
            else:
                print(f"Distance: {distance} mm")
            time.sleep(POLL_INTERVAL)
    finally:
        bus.close()

