import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x76
READ_INTERVAL = 5

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_bmp280(bus):
    try:
        data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 6)
        raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        return raw
    except OSError as e:
        raise RuntimeError(f"BMP280 read failed: {e}") from e


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.read_byte(I2C_ADDR)
        except OSError as e:
            print(f"Error: no BMP280 found at 0x{I2C_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        while running:
            try:
                value = read_bmp280(bus)
                print(f"BMP280 raw: {value}")
            except RuntimeError as e:
                print(f"Warning: {e}", file=sys.stderr)
            time.sleep(READ_INTERVAL)
    finally:
        bus.close()


