import time
import paho.mqtt.client as mqtt

BROKER_HOST = "localhost"
BROKER_PORT = 1883
PUBLISH_TOPIC = "sensor/data"
NUM_READINGS = 3
READ_TIMEOUT = 5.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
    else:
        print(f"Failed to connect to MQTT broker. Reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker. Reason code: {reason_code}")

def read_sensor_data():
    """Simulate reading sensor data. Returns (value, error_flag)."""
    try:
        value = 42
        return value, False
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, True

def publish_sensor_data(client, topic, data):
    try:
        info = client.publish(topic, str(data))
        info.wait_for_publish(timeout=5)
        print(f"Published data: {data} to topic: {topic}")
    except Exception as e:
        print(f"Error publishing data: {e}")

