    except Exception as e:
        print(f"Failed to connect to MQTT broker: {e}")
        sys.exit(1)

    client.loop_start()

    readings_taken = 0
    try:
        while readings_taken < NUM_READINGS and running:
            data, error = read_sensor_data()
