                print("Error reading sensor data. Skipping this reading.")
            else:
                if data is not None:
                    publish_sensor_data(client, PUBLISH_TOPIC, data)
                    readings_taken += 1
                else:
                    print("No data received from sensor. Skipping this reading.")
            time.sleep(1)
    finally:
        client.loop_stop()
        client.disconnect()
        print("Program finished.")

