    _running = False


def read_pcf8574(bus: SMBus) -> int | None:
    """Read a byte from the PCF8574 input port; return None on error."""
    try:
        return bus.read_byte(I2C_ADDR)
    except OSError as exc:
        print(f"Error: failed to read from PCF8574 at 0x{I2C_ADDR:02X}: {exc}", file=sys.stderr)
        return None


def is_valid(value: int | None) -> bool:
    """Reject None (error) and out-of-range values."""
    return value is not None and 0 <= value <= 0xFF


