def _write_register(bus, reg, value):
    msg = i2c_msg.write(INA219_ADDRESS, [reg, value])
    bus.i2c_rdwr(msg)


def _read_register(bus, reg):
    write_msg = i2c_msg.write(INA219_ADDRESS, [reg])
    read_msg = i2c_msg.read(INA219_ADDRESS, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)


def _read_measurement(bus):
    raw = _read_register(bus, 0x00)
    if raw is None or len(raw) < 2:
        return None
    value = (raw[0] << 8) | raw[1]
    if value == 0:
        return None
    return value


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _write_register(bus, 0x00, 0x00)
        time.sleep(0.1)

        while _running:
            try:
                measurement = _read_measurement(bus)
            except OSError as exc:
                print(f"Error: I2C read failed: {exc}", file=sys.stderr)
                break

            if measurement is None:
                print("Warning: invalid reading (0 or short read)", file=sys.stderr)
            else:
                print(f"Current: {measurement} mA")

            time.sleep(READ_INTERVAL_S)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

