        return True
    finally:
        trigger.close()
        echo.close()

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    for trigger_pin, echo_pin in zip(TRIGGER_PINS, ECHO_PINS):
        if not _running:
            break
        set_gpio_state(trigger_pin, echo_pin, 1)
        time.sleep(0.5)
        if not _running:
            break
        set_gpio_state(trigger_pin, echo_pin, 0)
        time.sleep(0.5)

