import time
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration
I2C_ADDRESS = 0x48
SAMPLE_INTERVAL = 0.1  # seconds
ADC_CHANNEL = 0


def initialize_adc():
    """Initialize I2C bus and ADS1115 ADC. Exit on failure."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ads = ADS.ADS1115(i2c, address=I2C_ADDRESS)
        ads.gain = 1
    except ValueError as e:
        print(f"Error: ADS1115 not found at address 0x{I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing ADS1115: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        channel = AnalogIn(ads, ADC_CHANNEL)
    except Exception as e:
        print(f"Error configuring ADC channel {ADC_CHANNEL}: {e}", file=sys.stderr)
        sys.exit(1)

    return i2c, ads, channel


def read_adc(channel):
    """Read and print ADC value. Return True on success, False on failure."""
    try:
        value = channel.value
        if value is None:
            print("Warning: ADC returned None (invalid reading).", file=sys.stderr)
            return False
        print(f"ADC Channel {channel.channel}: {value}")
        return True
    except OSError as e:
        print(f"Error reading ADC (I/O error): {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Error reading ADC: {e}", file=sys.stderr)
        return False


def main():
    i2c, ads, channel = initialize_adc()
    try:
        while True:
            read_adc(channel)
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Release hardware resources on all exit paths
        try:
            i2c.deinit()
        except Exception:
            pass
        try:
            ads.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

DYNAMO_GPIO_PIN = 18
POLL_INTERVAL = 0.1
MAX_POLL_SECONDS = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _wait_for_device(pin, timeout=MAX_POLL_SECONDS):
    """Poll the pin until it is ready or timeout expires."""
    deadline = time.monotonic() + timeout
    while _running and time.monotonic() < deadline:
        try:
            dev = OutputDevice(pin)
            if dev.is_active or not dev.is_active:
                return dev
        except GPIOZeroError:
            pass
        time.sleep(POLL_INTERVAL)
    return None


def _set_and_report(dev, state):
    """Apply a state to the output device and print the result."""
    try:
        dev.on() if state else dev.off()
        print(f"Applied state: {state}")
    except DeviceClosed:
        print("Error: device was closed before write.", file=sys.stderr)
        raise
    except GPIOZeroError as e:
        print(f"Error writing to GPIO {dev.pin}: {e}", file=sys.stderr)
        raise


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    dev = _wait_for_device(DYNAMO_GPIO_PIN)
    if dev is None:
        print(
            f"Error: could not initialize GPIO {DYNAMO_GPIO_PIN} within "
            f"{MAX_POLL_SECONDS:.1f} s.",
            file=sys.stderr,
        )
        sys.exit(1)

    try:
        _set_and_report(dev, True)
    except Exception:
        sys.exit(1)
    finally:
        try:
            dev.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import sys
import time
import signal
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers whose PWM state we report.
PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]

# Module-level reference so the signal handler can close devices.
_devices = []


def _cleanup(signum=None, frame=None):
    """Close every PWM device and exit."""
    for dev in _devices:
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def read_pwm_state(dev):
    """Return the current duty cycle of *dev* or None on error/invalid."""
    try:
        value = dev.value
    except GPIOZeroError:
        return None
    except Exception:
        return None

    if value is None or value < 0 or value > 1:
        return None
    return value


def main():
    # Register signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialize PWM devices.
    for pin in PWM_PINS:
        try:
            dev = PWMOutputDevice(pin, frequency=1000, initial_value=0)
            _devices.append(dev)
        except GPIOZeroError as exc:
            print(f"Error: failed to initialize PWM on GPIO{pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)
        except Exception as exc:
            print(f"Error: unexpected failure on GPIO{pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    try:
        while True:
            parts = []
            for dev in _devices:
                state = read_pwm_state(dev)
                if state is None:
                    parts.append("ERROR")
                else:
                    parts.append(f"{state:.3f}")
            print(" ".join(parts))
            time.sleep(1)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

import serial
import time
import sys
import signal

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_S = 1.0
READINGS = 3
INTERVAL_S = 2.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_serial_data(ser):
    """Read one line from the serial port and decode it."""
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('ascii', errors='replace').strip()

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT_S
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(READINGS):
            if not _running:
                break
            data = read_serial_data(ser)
            if data is not None:
                print(f"Reading {i + 1}/{READINGS}: {data}")
            else:
                print(f"Reading {i + 1}/{READINGS}: no data received")
            if i < READINGS - 1 and _running:
                time.sleep(INTERVAL_S)
    finally:
        ser.close()
        print("Serial port closed.")

if __name__ == "__main__":
    main()

