        for pin in PINS:
            try:
                dev = PWMOutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize PWM on GPIO{pin}: {exc}", file=sys.stderr)
                for d in devices:
                    d.close()
                sys.exit(1)

        while _running:
            for dev in devices:
                dev.value = 1.0
                print(f"GPIO{dev.pin.number} PWM set to 1.0")
                time.sleep(DELAY)
                dev.value = 0.0
                print(f"GPIO{dev.pin.number} PWM set to 0.0")
                time.sleep(DELAY)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import time
import sys
import signal
from smbus2 import SMBus, i2c_msg

AMG8833_ADDR = 0x69
I2C_BUS = 1
SAMPLE_INTERVAL = 0.1

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_amg8833(bus):
    try:
        # Trigger a measurement (0x00 register)
        bus.write_byte(AMG8833_ADDR, 0x00)
        time.sleep(0.01)
        # Read 128 bytes (64 pixels * 2 bytes each)
        data = bus.read_i2c_block_data(AMG8833_ADDR, 0x80, 128)
        if len(data) != 128:
            raise IOError(f"Expected 128 bytes, got {len(data)}")
        return data
    except OSError as e:
        raise IOError(f"AMG8833 read failed: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Verify device presence
        try:
            bus.read_byte(AMG8833_ADDR)
        except OSError:
            print(f"Error: no device found at I2C address 0x{AMG8833_ADDR:02X}", file=sys.stderr)
            sys.exit(1)

        while running:
            try:
                data = read_amg8833(bus)
                print(data)
            except IOError as e:
                print(f"Warning: {e}", file=sys.stderr)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

import time
import sys
import board
import busio
from adafruit_mcp3xxx import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn

# Configuration
ADC_CHANNEL = 0
SAMPLING_INTERVAL = 5  # seconds


def initialize_adc(channel: int) -> AnalogIn:
    """Initialize the MCP3008 ADC and return an AnalogIn object for the channel."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        mcp = MCP3008(i2c)
        return AnalogIn(mcp, channel)
    except Exception as e:
        print(f"Error initializing ADC: {e}", file=sys.stderr)
        sys.exit(1)


def read_adc(adc: AnalogIn) -> int | None:
    """Read the ADC value. Returns None if the reading is invalid."""
    try:
        value = adc.value
        if value is None or not (0 <= value <= 1023):
            print("Warning: Invalid ADC reading.", file=sys.stderr)
            return None
        return value
    except Exception as e:
        print(f"Error reading ADC: {e}", file=sys.stderr)
        return None


def main() -> None:
    """Main loop: read and print the ADC value every 5 seconds."""
    adc = initialize_adc(ADC_CHANNEL)
    try:
        while True:
            value = read_adc(adc)
            if value is not None:
                print(f"ADC Value: {value}")
            time.sleep(SAMPLING_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Release the I2C bus / hardware resources cleanly
        try:
            adc._pin.close()
        except Exception:
            pass
        try:
            adc._mcp._i2c.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

OUTPUT_PIN = 4

def main() -> int:
    try:
        output = DigitalOutputDevice(OUTPUT_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        return 1

    def cleanup(signum=None, frame=None):
        try:
            output.close()
        except Exception:
            pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        output.on()
        print(f"GPIO {OUTPUT_PIN} set to HIGH")
    except GPIOZeroError as exc:
        print(f"Failed to set GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        cleanup()
        return 1
    finally:
        cleanup()

    return 0

if __name__ == "__main__":
    sys.exit(main())

