import signal
import sys
from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [17, 18]

def read_state() -> int:
    """Return a valid state for the digital output.

    Returns 1 (active) or 0 (inactive).  If a valid state cannot be
    determined, return None to indicate the read should be rejected.
    """
    return 1

def apply_state(dev: DigitalOutputDevice, state: int) -> None:
    """Apply *state* to *dev* and print the result."""
    if state not in (0, 1):
        print(f"Invalid state {state} for output", file=sys.stderr)
        return
    dev.value = bool(state)
    print(f"Output set to: {state}")

def main() -> int:
    outputs = []
    try:
        for pin in PINS:
            dev = DigitalOutputDevice(pin)
            outputs.append(dev)

        for dev in outputs:
            state = read_state()
            if state is None:
                print("State read failed; skipping pin", file=sys.stderr)
                continue
            apply_state(dev, state)

        return 0

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user", file=sys.stderr)
        return 130
    finally:
        for dev in outputs:
            try:
                dev.close()
            except Exception:
                pass

if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time
import board
import adafruit_dht

DHT_PIN = board.D4
CYCLES = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                break
            try:
                temp = sensor.temperature
                hum = sensor.humidity
                if temp is not None and hum is not None:
                    print(f"Cycle {cycle}: T={temp:.1f}C  H={hum:.1f}%")
                else:
                    print(f"Cycle {cycle}: read failed (None)")
            except RuntimeError as exc:
                print(f"Cycle {cycle}: read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Cycle {cycle}: unexpected error: {exc}", file=sys.stderr)
            time.sleep(2.0)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()
